class StoreDB extends ChangeNotifier {
  SharedPreferences? prefs; List<Map<String, dynamic>> shops = []; int active = 0;
  bool get ready => prefs != null; Map<String, dynamic> get shop => shops.isEmpty ? <String, dynamic>{} : shops[active];
  Future<void> load() async { prefs = await SharedPreferences.getInstance(); try { final raw = jsonDecode(prefs!.getString('rentflow_data') ?? '[]'); if (raw is List) shops = raw.whereType<Map>().map((e) => Map<String, dynamic>.from(e)).toList(); } catch (_) { shops = []; } active = prefs!.getInt('rentflow_active') ?? 0; if (shops.isEmpty) active = 0; if (shops.isNotEmpty && active >= shops.length) active = shops.length - 1; notifyListeners(); }
  Future<void> save() async { await prefs?.setString('rentflow_data', jsonEncode(shops)); await prefs?.setInt('rentflow_active', active); notifyListeners(); }
  List<Map<String, dynamic>> records(String key) { if (shops.isEmpty) return []; final value = shop[key]; if (value is! List) return []; return value.whereType<Map>().map((e) => Map<String, dynamic>.from(e)).toList(); }
  Future<void> addShop(Map<String, dynamic> data) async { shops.add({...data, 'items': <Map<String, dynamic>>[], 'customers': <Map<String, dynamic>>[], 'issues': <Map<String, dynamic>>[], 'returns': <Map<String, dynamic>>[]}); active = shops.length - 1; await save(); }
  Future<void> updateShop(Map<String, dynamic> data) async { shop.addAll(data); await save(); }
  Future<void> addRecord(String key, Map<String, dynamic> data) async { final list = shop[key]; if (list is! List) shop[key] = <Map<String, dynamic>>[]; (shop[key] as List).add(data); await save(); }
  Future<void> editRecord(String key, int index, Map<String, dynamic> data) async { (shop[key] as List)[index] = data; await save(); }
  Future<void> deleteRecord(String key, int index) async { (shop[key] as List).removeAt(index); await save(); }
  Future<void> updateItemStock(String id, int delta) async { final items = shop['items'] as List; for (var i = 0; i < items.length; i++) { final item = Map<String, dynamic>.from(items[i] as Map); if ('${item['id']}' == id) { item['quantity'] = (int.tryParse('${item['quantity'] ?? 0}') ?? 0) + delta; items[i] = item; break; } } await save(); }
}
final store = StoreDB(); String newId() => DateTime.now().microsecondsSinceEpoch.toString(); void openPage(BuildContext context, Widget page) => Navigator.push(context, MaterialPageRoute(builder: (_) => page)); String today() => DateTime.now().toIso8601String().substring(0, 10); String money(dynamic value) => '₹${(double.tryParse('$value') ?? 0).toStringAsFixed(2)}';

