Future<void> printIssueBill(Map<String, dynamic> issue) async { final customers = store.records('customers'); final items = (issue['items'] as List? ?? []).map((e) => Map<String, dynamic>.from(e as Map)).toList(); String party = 'Customer'; for (final c in customers) { if ('${c['id']}' == '${issue['customerId']}') { party = '${c['name']}'; break; } } final shop = store.shop; final total = items.fold<double>(0, (sum, x) => sum + (double.tryParse('${x['rentPrice'] ?? 0}') ?? 0) * (int.tryParse('${x['qty'] ?? 0}') ?? 0) * (int.tryParse('${x['rentDays'] ?? 1}') ?? 1)); await Printing.layoutPdf(onLayout: (format) async { final doc = pw.Document(); doc.addPage(pw.Page(pageFormat: format, build: (_) => pw.Column(crossAxisAlignment: pw.CrossAxisAlignment.start, children: [pw.Text('${shop['name'] ?? 'RentFlow'}', style: pw.TextStyle(fontSize: 22, fontWeight: pw.FontWeight.bold)), pw.Text('Rental Invoice • By PaliaAPK HUB'), pw.SizedBox(height: 12), pw.Text('Invoice: ${issue['invoice']}'), pw.Text('Customer: $party'), pw.Text('Date: ${issue['date']}'), pw.SizedBox(height: 15), pw.Table.fromTextArray(headers: const ['Item', 'Qty', 'Rent/Day', 'Days', 'Amount'], data: items.map((x) { final q = int.tryParse('${x['qty'] ?? 0}') ?? 0; final r = double.tryParse('${x['rentPrice'] ?? 0}') ?? 0; final d = int.tryParse('${x['rentDays'] ?? 1}') ?? 1; return ['${x['name']}', '$q', money(r), '$d', money(r * q * d)]; }).toList()), pw.SizedBox(height: 12), pw.Align(alignment: pw.Alignment.centerRight, child: pw.Text('Total Rent: ${money(total)}', style: pw.TextStyle(fontSize: 16, fontWeight: pw.FontWeight.bold))), pw.SizedBox(height: 28), pw.Text('Thank you • Developer by shanpalia')]))); return doc.save(); }); }
Future<void> printReturnBill(Map<String, dynamic> ret) async { final customers = store.records('customers'); String party = 'Customer'; for (final c in customers) { if ('${c['id']}' == '${ret['customerId']}') { party = '${c['name']}'; break; } } final items = (ret['items'] as List? ?? []).map((e) => Map<String, dynamic>.from(e as Map)).toList(); await Printing.layoutPdf(onLayout: (format) async { final doc = pw.Document(); doc.addPage(pw.Page(pageFormat: format, build: (_) => pw.Column(crossAxisAlignment: pw.CrossAxisAlignment.start, children: [pw.Text('${store.shop['name'] ?? 'RentFlow'}', style: pw.TextStyle(fontSize: 22, fontWeight: pw.FontWeight.bold)), pw.Text('Return Receipt • By PaliaAPK HUB'), pw.SizedBox(height: 12), pw.Text('Return No: ${ret['returnInvoice'] ?? ret['id']}'), pw.Text('Customer: $party'), pw.Text('Date: ${ret['date']}'), pw.SizedBox(height: 15), pw.Table.fromTextArray(headers: const ['Item', 'Return Qty', 'Rent/Day', 'Days', 'Amount'], data: items.map((x) => ['${x['name']}', '${x['qty']}', money(x['rentPrice']), '${x['rentDays']}', money(x['rentAmount'])]).toList()), pw.SizedBox(height: 12), pw.Align(alignment: pw.Alignment.centerRight, child: pw.Text('Return Rent: ${money(ret['amount'])}', style: pw.TextStyle(fontSize: 16, fontWeight: pw.FontWeight.bold))), pw.SizedBox(height: 20), pw.Text('Note: ${ret['notes'] ?? ''}')]))); return doc.save(); }); }
